use std::fs
use std::env
use std::process

fn emit(text: string, number: bool, counter: int) -> int {
    if !number {
        print(text)
        return counter
    }
    let mut parts: Vec<string> = text.split("\n").collect()
    if parts.len() > 0 && parts[parts.len() - 1] == "" {
        parts.pop()
    }
    let mut n = counter
    for line in parts {
        n += 1
        println("${n:>6}\t${line}")
    }
    n
}

fn main() {
    let mut number = false
    let mut files: Vec<string> = []
    let mut first = true
    for a in env::args() {
        if first {
            first = false
            continue
        }
        if a == "-n" {
            number = true
        } else {
            files.push(a)
        }
    }
    let mut counter = 0
    let mut failed = false
    if files.len() == 0 {
        let text = fs::read_to_string("/dev/stdin").unwrap_or("")
        counter = emit(text, number, counter)
    }
    for f in files {
        match fs::read_to_string(f) {
            Ok(text) => { counter = emit(text, number, counter) }
            Err(_) => {
                println("cat: ${f}: No such file")
                failed = true
            }
        }
    }
    if failed {
        process::exit(1)
    }
}
